/**
 * STOMP over WebSocket Client v2.3.3 (DentalCare Luxury Clinic Local Vendorized Edition)
 * Enables 100% offline and local clinic LAN operation without external CDNs
 */
(function (global) {
    'use strict';

    const Byte = {
        LF: '\x0A',
        NULL: '\x00'
    };

    function Frame(command, headers, body) {
        this.command = command || '';
        this.headers = headers || {};
        this.body = body || '';
    }

    Frame.prototype.toString = function () {
        const lines = [this.command];
        for (const key in this.headers) {
            if (Object.prototype.hasOwnProperty.call(this.headers, key)) {
                lines.push(key + ':' + this.headers[key]);
            }
        }
        lines.push('');
        lines.push(this.body);
        return lines.join(Byte.LF) + Byte.NULL;
    };

    Frame.unmarshall = function (datas) {
        // Split on NULL byte
        const rawFrames = datas.split(RegExp('' + Byte.NULL + '(?:\x0A)?'));
        const frames = [];

        for (let i = 0; i < rawFrames.length; i++) {
            const raw = rawFrames[i];
            if (!raw || raw.trim().length === 0) continue;

            // Trim leading newlines (heartbeats)
            const clean = raw.replace(/^\x0A+/, '');
            if (!clean) continue;

            const divider = clean.indexOf('\x0A\x0A');
            if (divider === -1) continue;

            const headerPart = clean.slice(0, divider);
            const body = clean.slice(divider + 2);

            const headerLines = headerPart.split('\x0A');
            const command = headerLines[0].trim();
            const headers = {};

            for (let j = 1; j < headerLines.length; j++) {
                const line = headerLines[j];
                const colonIdx = line.indexOf(':');
                if (colonIdx !== -1) {
                    const key = line.slice(0, colonIdx).trim();
                    const val = line.slice(colonIdx + 1).trim();
                    if (!headers[key]) {
                        headers[key] = val;
                    }
                }
            }

            frames.push(new Frame(command, headers, body));
        }

        return frames;
    };

    function Client(ws) {
        this.ws = ws;
        this.subscriptions = {};
        this.counter = 0;
        this.connected = false;
        this.heartbeat = { outgoing: 10000, incoming: 10000 };
        this.maxWebSocketFrameSize = 16 * 1024;
        this.debug = function (message) {
            // Can be suppressed or set by caller
        };
    }

    Client.prototype._transmit = function (command, headers, body) {
        const frame = new Frame(command, headers, body);
        if (typeof this.debug === 'function') {
            this.debug('>>> ' + frame.command);
        }
        this.ws.send(frame.toString());
    };

    Client.prototype.connect = function () {
        const args = Array.prototype.slice.call(arguments);
        let headers = {};
        let connectCallback = null;
        let errorCallback = null;
        let closeEventCallback = null;

        if (typeof args[0] === 'object' && args[0] !== null) {
            headers = args.shift();
        }
        if (typeof args[0] === 'function') {
            connectCallback = args.shift();
        }
        if (typeof args[0] === 'function') {
            errorCallback = args.shift();
        }
        if (typeof args[0] === 'function') {
            closeEventCallback = args.shift();
        }

        const self = this;

        const performConnect = function () {
            headers['accept-version'] = '1.1,1.0';
            headers['heart-beat'] = [self.heartbeat.outgoing, self.heartbeat.incoming].join(',');
            self._transmit('CONNECT', headers, '');
        };

        this.ws.onopen = function () {
            performConnect();
        };

        // If ws is already open when connect() is called
        if (this.ws.readyState === 1) {
            performConnect();
        }

        this.ws.onmessage = function (event) {
            const data = event.data;
            if (typeof self.debug === 'function') {
                self.debug('<<< ' + (typeof data === 'string' ? data.slice(0, 100) : 'binary'));
            }

            const frames = Frame.unmarshall(data);
            for (let i = 0; i < frames.length; i++) {
                const frame = frames[i];

                switch (frame.command) {
                    case 'CONNECTED':
                        self.connected = true;
                        if (typeof self.debug === 'function') {
                            self.debug('connected to server ' + (frame.headers.server || ''));
                        }
                        if (connectCallback) {
                            connectCallback(frame);
                        }
                        break;

                    case 'MESSAGE':
                        const subId = frame.headers.subscription;
                        const onReceive = self.subscriptions[subId];
                        if (onReceive) {
                            // Provide ack / nack helper on the message frame
                            frame.ack = function (ackHeaders) {
                                self._transmit('ACK', Object.assign({ id: frame.headers['message-id'], subscription: subId }, ackHeaders));
                            };
                            frame.nack = function (nackHeaders) {
                                self._transmit('NACK', Object.assign({ id: frame.headers['message-id'], subscription: subId }, nackHeaders));
                            };
                            onReceive(frame);
                        } else if (typeof self.debug === 'function') {
                            self.debug('Unhandled received MESSAGE: ' + frame);
                        }
                        break;

                    case 'RECEIPT':
                        if (self.onreceipt) self.onreceipt(frame);
                        break;

                    case 'ERROR':
                        if (errorCallback) {
                            errorCallback(frame);
                        }
                        break;

                    default:
                        if (typeof self.debug === 'function') {
                            self.debug('Unhandled frame: ' + frame.command);
                        }
                        break;
                }
            }
        };

        this.ws.onclose = function (event) {
            self.connected = false;
            if (closeEventCallback) {
                closeEventCallback(event);
            } else if (errorCallback) {
                errorCallback(event);
            }
        };

        this.ws.onerror = function (error) {
            if (errorCallback) {
                errorCallback(error);
            }
        };
    };

    Client.prototype.disconnect = function (disconnectCallback, headers) {
        headers = headers || {};
        this._transmit('DISCONNECT', headers, '');
        this.ws.onclose = null;
        try {
            this.ws.close();
        } catch (e) {}
        this.connected = false;
        if (disconnectCallback) {
            disconnectCallback();
        }
    };

    Client.prototype.send = function (destination, headers, body) {
        headers = headers || {};
        headers.destination = destination;
        this._transmit('SEND', headers, body || '');
    };

    Client.prototype.subscribe = function (destination, callback, headers) {
        headers = headers || {};
        if (!headers.id) {
            headers.id = 'sub-' + this.counter++;
        }
        headers.destination = destination;
        this.subscriptions[headers.id] = callback;
        this._transmit('SUBSCRIBE', headers, '');

        const self = this;
        const subId = headers.id;

        return {
            id: subId,
            unsubscribe: function () {
                self.unsubscribe(subId);
            }
        };
    };

    Client.prototype.unsubscribe = function (id) {
        delete this.subscriptions[id];
        this._transmit('UNSUBSCRIBE', { id: id }, '');
    };

    const Stomp = {
        Frame: Frame,
        over: function (ws) {
            return new Client(ws);
        },
        client: function (url, protocols) {
            const NativeWebSocket = typeof WebSocket !== 'undefined' ? WebSocket : (typeof window !== 'undefined' ? window.WebSocket : null);
            const ws = new NativeWebSocket(url, protocols);
            return new Client(ws);
        }
    };

    // Export to global / UMD
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Stomp;
    }
    if (typeof global !== 'undefined') {
        global.Stomp = Stomp;
    }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
